const BOSS_PORTRAIT_CACHE = {};

function _compositePortraitSlot(cacheKey, w, h, rgbSrc, maskSrc) {
  let rec = BOSS_PORTRAIT_CACHE[cacheKey];
  if (rec) return rec.ready ? rec.canvas : null;
  if (typeof Image === 'undefined' || typeof document === 'undefined' || !rgbSrc || !maskSrc) return null;

  rec = { ready: false, canvas: null, rgbImg: new Image(), maskImg: new Image(), loaded: 0 };
  BOSS_PORTRAIT_CACHE[cacheKey] = rec;

  const tryComposite = () => {
    rec.loaded++;
    if (rec.loaded < 2) return;
    if (!rec.rgbImg.naturalWidth || !rec.maskImg.naturalWidth) return;
    const c = document.createElement('canvas');
    c.width = w;
    c.height = h;
    const g = c.getContext('2d');
    if (!g) return;
    g.clearRect(0, 0, w, h);
    g.drawImage(rec.rgbImg, 0, 0, w, h);
    g.globalCompositeOperation = 'destination-in';
    g.drawImage(rec.maskImg, 0, 0, w, h);
    g.globalCompositeOperation = 'source-over';
    rec.canvas = c;
    rec.ready = true;
    rec.rgbImg = null;
    rec.maskImg = null;
  };

  rec.rgbImg.onload = tryComposite;
  rec.maskImg.onload = tryComposite;
  rec.rgbImg.src = rgbSrc;
  rec.maskImg.src = maskSrc;
  return null;
}

function getBossAnimePortrait(variant, isMythic = false) {
  const spec = BOSS_PORTRAIT_DATA && BOSS_PORTRAIT_DATA[variant];
  if (!spec) return null;
  if (isMythic && spec.mythicRgb && spec.mythicMask) {
    const mythicCanvas = _compositePortraitSlot(variant + '__mythic', spec.w, spec.h, spec.mythicRgb, spec.mythicMask);
    if (mythicCanvas) return mythicCanvas;
  }
  return _compositePortraitSlot(variant, spec.w, spec.h, spec.rgb, spec.mask);
}

function preloadAllBossPortraits() {
  if (typeof Image === 'undefined' || typeof document === 'undefined') return;
  const keys = Object.keys(BOSS_PORTRAIT_DATA);
  for (let i = 0; i < keys.length; i++) {
    getBossAnimePortrait(keys[i], false);
    getBossAnimePortrait(keys[i], true);
  }
}

preloadAllBossPortraits();
